// Generated by tools/build_appellations.py from the Vitis Mundi atlas. Do not edit by hand.
APX.ca = {"country":{"name":"Canada","tagline":"A cold-climate wine country that turned its hardest winters into icewine, and is now learning to make Chardonnay, Pinot Noir and Cabernet Franc to match.","classification":"Canada has no federal appellation system; wine origin is a provincial matter. Ontario: VQA Ontario (Vintners Quality Alliance Act, 1999) recognises three primary appellations (Niagara Peninsula, Lake Erie North Shore, Prince Edward County), two regional appellations within the Niagara Peninsula (Niagara-on-the-Lake and Niagara Escarpment) and 11 sub-appellations (10 in Niagara plus South Islands). VQA wines must be 100 percent Ontario-grown, at least 85 percent from a named appellation, and pass laboratory and tasting tests. British Columbia: BC VQA and the BC Wine Authority recognise the British Columbia GI, nine regional GIs and 12 sub-GIs (11 in the Okanagan plus Cowichan Valley); wines naming a GI need at least 95 percent of grapes from it. Icewine everywhere must come from grapes naturally frozen on the vine, picked at minus 8 degrees Celsius or colder, with at least 35 degrees Brix. Quebec: the IGP Vin du Québec covers wines from 100 percent Quebec grapes; separate IGPs protect Vin de glace du Québec and Cidre de glace du Québec. Nova Scotia: Tidal Bay is a provincial appellation-style designation for blended whites. 'International-Canadian Blends' may contain mostly imported wine."},"regions":[{"name":"Ontario","slug":"ontario","tagline":"Lake-moderated vineyards on the Niagara benches, Lake Erie's warm shore and Prince Edward County's limestone.","ids":["ca-beamsville-bench","ca-creek-shores","ca-four-mile-creek","ca-lake-erie-north-shore","ca-lincoln-lakeshore","ca-niagara-escarpment","ca-niagara-lakeshore","ca-niagara-peninsula","ca-niagara-river","ca-niagara-on-the-lake","ca-prince-edward-county","ca-short-hills-bench","ca-south-islands","ca-st-davids-bench","ca-twenty-mile-bench","ca-vinemount-ridge"]},{"name":"British Columbia","slug":"british-columbia","tagline":"Desert benches above glacial lakes, island vineyards and mountain valleys at the edge of viable viticulture.","ids":["ca-cowichan-valley","ca-east-kelowna-slopes","ca-fraser-valley","ca-golden-mile-bench","ca-golden-mile-slopes","ca-gulf-islands","ca-kootenays","ca-lake-country","ca-lillooet","ca-naramata-bench","ca-okanagan-falls","ca-okanagan-valley","ca-shuswap","ca-similkameen-valley","ca-skaha-bench","ca-south-kelowna-slopes","ca-summerland-bench","ca-summerland-lakefront","ca-summerland-valleys","ca-thompson-valley","ca-vancouver-island"]},{"name":"Quebec","slug":"quebec","tagline":"Hybrids under winter blankets, and the birthplace of ice cider.","ids":["ca-cidre-de-glace-du-quebec","ca-vin-de-glace-du-quebec","ca-vin-du-quebec"]},{"name":"Nova Scotia","slug":"nova-scotia","tagline":"Tidal valleys on the Bay of Fundy, crisp whites and world-class sparkling wine.","ids":["ca-tidal-bay"]}],"items":{"ca-beamsville-bench":{"name":"Beamsville Bench","cat":"VQA","region":"Ontario","subregion":"Niagara Escarpment","styles":["white","red","sweet"],"summary":"The western escarpment bench around Beamsville, with steep, northward-facing slopes, well-drained clay-loam over dolomitic limestone and the most frost-free days on the escarpment (about 217); 12 wineries. Known for taut Riesling, Chardonnay and Pinot Noir.","producers":["Hidden Bench","Thirty Bench","Rosewood","Fielding (near)","Bachelder (sourcing)"],"rslug":"ontario"},"ca-cidre-de-glace-du-quebec":{"name":"Cidre de glace du Québec","cat":"IGP","region":"Quebec","styles":["sweet"],"grapes":"Apples","summary":"Quebec's IGP for ice cider, made from apples or apple juice concentrated by natural winter cold. Christian Barthomeuf of Domaine des Côtes d'Ardoise is credited with inventing it around 1989; Domaine Pinnacle and La Face Cachée de la Pomme made it famous. Not a grape wine, but a Quebec signature alongside icewine.","producers":["Domaine Pinnacle","La Face Cachée de la Pomme","Domaine des Côtes d'Ardoise"],"rslug":"quebec"},"ca-cowichan-valley":{"name":"Cowichan Valley","cat":"GI","region":"British Columbia","subregion":"Vancouver Island","styles":["red","white"],"grapes":"Pinot Noir, Pinot Gris, Ortega, Chardonnay","summary":"Vancouver Island's sub-GI, a warm pocket north of Victoria (its name is said to mean 'warm land' in Hul'q'umi'num). Pinot Noir, Pinot Gris and sparkling wine from small family wineries.","producers":["Blue Grouse","Averill Creek","Unsworth","Venturi-Schulze"],"rslug":"british-columbia"},"ca-creek-shores":{"name":"Creek Shores","cat":"VQA","region":"Ontario","subregion":"Niagara Peninsula","styles":["white","red","sweet"],"summary":"A lakeshore-plain sub-appellation between St. Catharines and Jordan, crossed by creeks (Twenty Mile, Fifteen Mile, Sixteen Mile) that drain the escarpment; about 1,550 growing degree days. Lake Ontario and the creeks moderate temperatures.","producers":["Harbour Estates","Rockway"],"rslug":"ontario"},"ca-east-kelowna-slopes":{"name":"East Kelowna Slopes","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Riesling, Pinot Noir, Chardonnay, Pinot Gris","summary":"A sub-GI (2022) of about 2,900 ha in the hills east of Kelowna, higher and cooler, home to Tantalus, whose old-vine Riesling comes from vines planted in 1978.","producers":["Tantalus"],"rslug":"british-columbia"},"ca-four-mile-creek":{"name":"Four Mile Creek","cat":"VQA","region":"Ontario","subregion":"Niagara-on-the-Lake","styles":["white","red","sweet"],"summary":"Sub-appellation on the flat plain of Niagara-on-the-Lake around Four Mile Creek, with heavy clay-loam soils and about 1,582 growing degree days; warm, early-ripening sites for Cabernet Franc, Merlot and icewine Vidal.","producers":["Château des Charmes (estate parcels)","Peller","Jackson-Triggs"],"rslug":"ontario"},"ca-fraser-valley":{"name":"Fraser Valley","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"1990","styles":["red","white"],"grapes":"Pinot Gris, Bacchus, Pinot Noir, Siegerrebe","summary":"A coastal GI in the lower Fraser River valley east of Vancouver, with a wet, mild climate; mostly early-ripening whites and Pinot Noir, and many wineries using Okanagan grapes.","producers":["Domaine de Chaberton"],"rslug":"british-columbia"},"ca-golden-mile-bench":{"name":"Golden Mile Bench","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2015","styles":["red","white"],"grapes":"Merlot, Cabernet Franc, Syrah, Chardonnay, Gewürztraminer","summary":"BC's first sub-GI (2015), a 21 km-long, east-facing glacial bench and alluvial fans on the west side of the valley south of Oliver. Gravelly, well-drained soils and morning sun give ripe yet fresh Bordeaux varieties, Syrah and aromatic whites. The name dates from the gold rush at Fairview in the 1890s.","producers":["Tinhorn Creek","Road 13","Checkmate","Culmina","Hester Creek","Fairview Cellars"],"rslug":"british-columbia"},"ca-golden-mile-slopes":{"name":"Golden Mile Slopes","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","styles":["red","white"],"grapes":"Merlot, Cabernet Sauvignon, Syrah, Pinot Gris","summary":"A sub-GI covering the steeper slopes and higher ground above the Golden Mile Bench west of Oliver, with shallower, rockier soils and later afternoon shade; Bordeaux varieties, Syrah and whites.","producers":["Culmina (upper parcels)","Gehringer Brothers"],"rslug":"british-columbia"},"ca-gulf-islands":{"name":"Gulf Islands","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"1990","styles":["red","white"],"grapes":"Pinot Noir, Pinot Gris, Gewürztraminer","summary":"A coastal GI covering the islands between Vancouver Island and the mainland (Salt Spring, Pender, Saturna), in the rain shadow of the Olympic and Vancouver Island mountains; small producers of Pinot Noir and aromatic whites.","producers":["Salt Spring Vineyards","Garry Oaks"],"rslug":"british-columbia"},"ca-kootenays":{"name":"Kootenays","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"2018","styles":["red","white"],"grapes":"Pinot Noir, Chardonnay, Gewürztraminer","summary":"A GI (2018) in the mountain valleys of southeastern BC, chiefly the Creston Valley, a warm pocket near the US border; Pinot Noir, Chardonnay and aromatic whites.","producers":["Baillie-Grohman","Wynnwood"],"rslug":"british-columbia"},"ca-lake-country":{"name":"Lake Country","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Pinot Noir, Riesling, Gewürztraminer, Pinot Gris, Chardonnay","summary":"The northernmost Okanagan sub-GI (2022), about 2,500 ha around Winfield and Oyama between Kelowna and Vernon. Cool and lake-moderated; Pinot Noir, Riesling, Gewürztraminer and sparkling. George and Trudy Heiss planted Gray Monk's vineyard in 1972 and pioneered German and Alsace varieties here.","producers":["Gray Monk","50th Parallel","Ex Nihilo","Intrigue"],"rslug":"british-columbia"},"ca-lake-erie-north-shore":{"name":"Lake Erie North Shore","cat":"VQA","region":"Ontario","created":"1988","styles":["red","white","sweet"],"grapes":"Cabernet Sauvignon, Cabernet Franc, Merlot, Riesling, Chardonnay, Vidal","summary":"Ontario's southernmost and warmest mainland appellation, a bow-shaped strip along Lake Erie from Amherstburg to near St. Thomas at about 42 degrees north. Shallow Lake Erie warms quickly, giving more growing degree days than any other Ontario region; red Bordeaux varieties ripen well. Colio Estate (1980) at Harrow is the oldest modern winery; about 15 wineries.","producers":["Colio Estate","Pelee Island Winery","Cooper's Hawk","Oxley Estate"],"contains":["South Islands"],"rslug":"ontario"},"ca-lillooet":{"name":"Lillooet","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"2018","styles":["red","white"],"grapes":"Cabernet Franc, Merlot, Pinot Noir, Riesling","summary":"A GI (2018) in the Fraser Canyon around Lillooet, a hot, dry rain-shadow pocket with long summer days; a handful of wineries such as Fort Berens grow Bordeaux varieties and Riesling.","producers":["Fort Berens"],"rslug":"british-columbia"},"ca-lincoln-lakeshore":{"name":"Lincoln Lakeshore","cat":"VQA","region":"Ontario","subregion":"Niagara Peninsula","styles":["white","red","sweet"],"summary":"A flat, lake-cooled sub-appellation along Lake Ontario in the Town of Lincoln, with a long frost-free season (about 198 days) but cooler summers (about 1,527 growing degree days); it supplies grapes to many Niagara wineries.","producers":["Kacaba (nearby)","growers"],"rslug":"ontario"},"ca-naramata-bench":{"name":"Naramata Bench","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2019","styles":["red","white"],"grapes":"Pinot Noir, Merlot, Syrah, Pinot Gris, Gewürztraminer, Chardonnay","summary":"A sub-GI (2019) along the east shore of Okanagan Lake north of Penticton, with about 40 wineries on west-facing glacial benches and silt bluffs above the lake. Lake reflection and evening warmth suit Pinot Noir, Merlot, Syrah and aromatic whites; it is one of BC's most visited wine roads.","producers":["La Frenz","Laughing Stock","Poplar Grove","Moraine","Lake Breeze","Terravista"],"rslug":"british-columbia"},"ca-niagara-escarpment":{"name":"Niagara Escarpment","cat":"VQA","region":"Ontario","subregion":"Niagara Peninsula","styles":["white","red","sparkling"],"grapes":"Chardonnay, Riesling, Pinot Noir, Cabernet Franc, Gamay","summary":"A regional appellation joining the three bench sub-appellations (Short Hills, Twenty Mile, Beamsville) along the escarpment between St. Catharines and Grimsby, with 25 wineries. Fossil-rich limestone and dolomite soils, slopes and lake breezes give Ontario's most mineral Riesling and Chardonnay. Not to be confused with the US Niagara Escarpment AVA across the river in New York.","producers":["Tawse","Cave Spring","Hidden Bench","Thirty Bench","Flat Rock","Pearl Morissette"],"contains":["Short Hills Bench","Twenty Mile Bench","Beamsville Bench"],"rslug":"ontario"},"ca-niagara-lakeshore":{"name":"Niagara Lakeshore","cat":"VQA","region":"Ontario","subregion":"Niagara-on-the-Lake","styles":["white","red","sweet"],"summary":"Sub-appellation on the shore of Lake Ontario around the town of Niagara-on-the-Lake, with the longest frost-free season in Niagara (about 213 days) and around 1,563 growing degree days; lake breezes keep it frost-free late into autumn.","producers":["Konzelmann","Strewn"],"rslug":"ontario"},"ca-niagara-on-the-lake":{"name":"Niagara-on-the-Lake","cat":"VQA","region":"Ontario","subregion":"Niagara Peninsula","styles":["red","white","sweet"],"grapes":"Cabernet Franc, Merlot, Cabernet Sauvignon, Chardonnay, Riesling, Vidal","summary":"A regional appellation covering the plain below the escarpment between St. Catharines and the Niagara River, with four sub-appellations. It is the warmest, most-visited part of Niagara (39 wineries, about 1,597 growing degree days) and the heartland of Ontario icewine and Bordeaux reds.","producers":["Inniskillin","Stratus","Château des Charmes","Peller","Southbrook"],"contains":["Niagara River","Niagara Lakeshore","Four Mile Creek","St. David's Bench"],"rslug":"ontario"},"ca-niagara-peninsula":{"name":"Niagara Peninsula","cat":"VQA","region":"Ontario","created":"1988","styles":["white","red","sweet","sparkling","rose"],"grapes":"Riesling, Chardonnay, Cabernet Franc, Cabernet Sauvignon, Merlot, Pinot Noir, Pinot Gris, Gamay, Vidal","summary":"Canada's largest appellation and the source of most Ontario VQA wine: 13,600 acres and 105 wineries in 2024 to 2025. The Niagara Escarpment and Lake Ontario create a protected corridor where over 40 varieties ripen. Benchland vineyards along the escarpment give the most structured Riesling and Chardonnay; the warmer lake plain gives Cabernet Franc, Merlot and much of Ontario's icewine.\n\nThe Niagara Escarpment, a limestone ridge that runs from New York to Wisconsin and is a UNESCO biosphere reserve in Ontario, is the key to the appellation. Air off Lake Ontario hits the escarpment and circulates back, so the benches stay a few degrees warmer on cold winter nights and cooler in summer heat. Even so, deep freezes (as in the polar-vortex winters of 2014 and 2015) can kill buds, so growers bury graft unions, run wind machines and plant hardy varieties. Niagara's best Chardonnay and Riesling are among the finest cool-climate wines in North America.","producers":["Inniskillin","Château des Charmes","Cave Spring","Tawse","Hidden Bench","Southbrook","Stratus","Pearl Morissette","Henry of Pelham"],"contains":["Niagara-on-the-Lake","Niagara Escarpment","Creek Shores","Lincoln Lakeshore","Vinemount Ridge"],"rslug":"ontario"},"ca-niagara-river":{"name":"Niagara River","cat":"VQA","region":"Ontario","subregion":"Niagara-on-the-Lake","styles":["white","red","sweet"],"summary":"Sub-appellation (Niagara-on-the-Lake) along the Niagara River, where the deep, fast-moving river carries warm air and keeps frost away; about 1,606 growing degree days and 199 frost-free days. Warm enough for Cabernet Sauvignon and Merlot as well as icewine.","producers":["Inniskillin","Reif Estate","Riverview"],"rslug":"ontario"},"ca-okanagan-falls":{"name":"Okanagan Falls","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2018","styles":["red","white"],"grapes":"Pinot Noir, Chardonnay, Pinot Gris, Riesling, Syrah","summary":"A sub-GI (2018) around the town of Okanagan Falls between Skaha and Vaseux lakes, with a varied mix of benches, granitic slopes and glacial lake sediments. Blue Mountain's Pinot Noir and sparkling wines made its name.","producers":["Blue Mountain","Liquidity","Meyer Family","Noble Ridge","Synchromesh"],"rslug":"british-columbia"},"ca-okanagan-valley":{"name":"Okanagan Valley","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"1990","styles":["red","white"],"grapes":"Merlot, Pinot Noir, Chardonnay, Pinot Gris, Cabernet Franc, Syrah, Cabernet Sauvignon, Riesling","summary":"BC's dominant GI, with about 90 percent of the province's vineyards along 175 km of glacial lakes. It runs from the semi-desert around Osoyoos and Oliver, the warmest place in Canada for grapes, to cooler Kelowna and Lake Country. Bordeaux varieties and Syrah dominate the south; Pinot Noir, Chardonnay, Pinot Gris, Riesling and sparkling the north. Eleven sub-GIs (2015 to 2022) mark out its benches and slopes.\n\nThe valley's north-south axis and its chain of lakes create a steep climate gradient: the desert floor around Osoyoos is among the hottest vineyard land in Canada, while Lake Country, about 175 km north, is much cooler and suited to Riesling and sparkling wine. Long summer days at 49 to 50 degrees north give extra ripening hours, and cold nights keep acidity. The frosts of 2022 and 2024 forced many growers to rethink varieties, with more cold-hardy clones and the replanting of almost all damaged blocks by 2026.","producers":["Mission Hill","Burrowing Owl","Quails' Gate","Osoyoos Larose","Painted Rock","Blue Mountain","Tantalus","CedarCreek","Nk'Mip"],"contains":["Golden Mile Bench","Golden Mile Slopes","Okanagan Falls","Skaha Bench","Naramata Bench","Summerland Bench","Summerland Lakefront","Summerland Valleys","South Kelowna Slopes","East Kelowna Slopes","Lake Country"],"rslug":"british-columbia"},"ca-prince-edward-county":{"name":"Prince Edward County","cat":"VQA","region":"Ontario","created":"2007","styles":["red","white","sparkling","rose"],"grapes":"Pinot Noir, Chardonnay, Pinot Gris, Riesling, Cabernet Franc","summary":"Ontario's newest and coolest primary appellation (2007), an island-like county in Lake Ontario east of Toronto. Shallow clay loam over fractured Trenton limestone drew winemakers looking for Burgundian conditions; the downside is winter cold so severe that many growers bury their vines under soil each autumn and dig them out in spring. Pinot Noir and Chardonnay are taut, mineral and low in alcohol; Norman Hardie, Closson Chase, Hinterland (sparkling) and Rosehall Run are leading names.\n\nBurying vines is labour-intensive: in late autumn, growers prune and lay canes in a trench and cover them with soil, then uncover them in spring. That helps them survive winter lows that can fall below minus 25 degrees Celsius. The County has a few dozen wineries, many of them small and family-run, and its Pinot Noir and Chardonnay have drawn comparisons to Burgundy's cooler villages.","producers":["Norman Hardie","Closson Chase","Hinterland","Rosehall Run","Trail Estate","Grange of Prince Edward"],"rslug":"ontario"},"ca-short-hills-bench":{"name":"Short Hills Bench","cat":"VQA","region":"Ontario","subregion":"Niagara Escarpment","styles":["white","red","sweet"],"summary":"The easternmost escarpment bench, a hilly area southwest of St. Catharines around Twelve Mile Creek; relatively far from the lake, it has hot summers but fewer frost-free days (about 187). Henry of Pelham's family estate dates to a land grant of 1794.","producers":["Henry of Pelham","Hinterbrook"],"rslug":"ontario"},"ca-shuswap":{"name":"Shuswap","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"2018","styles":["red","white"],"grapes":"Siegerrebe, Ortega, Pinot Noir, Maréchal Foch","summary":"A GI (2018) around Shuswap Lake and Salmon Arm, north of the Okanagan, cooler and wetter, with a short season. Growers favour early-ripening vinifera such as Siegerrebe and Ortega and cold-hardy hybrids; Larch Hills claims one of the highest-elevation vineyards in BC.","producers":["Larch Hills","Recline Ridge"],"rslug":"british-columbia"},"ca-similkameen-valley":{"name":"Similkameen Valley","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"1990","styles":["red","white"],"grapes":"Syrah, Cabernet Franc, Merlot, Riesling, Chardonnay","summary":"A narrow, hot valley GI west of the Okanagan around Cawston and Keremeos, walled by rock cliffs that radiate heat, with strong winds that keep disease low. It is known as Canada's organic farming capital; Syrah, Cabernet Franc, Merlot and Riesling.","producers":["Clos du Soleil","Orofino","Corcelettes","Forbidden Fruit"],"rslug":"british-columbia"},"ca-skaha-bench":{"name":"Skaha Bench","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2019","styles":["red","white"],"grapes":"Merlot, Cabernet Franc, Syrah, Chardonnay","summary":"A sub-GI (2019) on the east side of Skaha Lake south of Penticton: a steep, west-facing bench of glacial silt, sand and gravel that catches afternoon sun reflected off the lake. Painted Rock's Bordeaux blends and Syrahs are the benchmark.","producers":["Painted Rock","Pentâge","Blasted Church","Kraze Legz"],"rslug":"british-columbia"},"ca-south-islands":{"name":"South Islands","cat":"VQA","region":"Ontario","subregion":"Lake Erie North Shore","created":"2015","styles":["red","white","sweet"],"grapes":"Cabernet Franc, Pinot Noir, Riesling, Chardonnay, Tempranillo, Vidal","summary":"A sub-appellation (July 2015) covering the nine islands of the Township of Pelee in Lake Erie, at Canada's southernmost point. Grapes grow mainly on Pelee Island, about 20 km offshore, where the growing season can be 30 days longer than on the mainland and harvest begins in August. Vin Villa, Canada's first commercial winery, opened here in 1866; Pelee Island Winery farms the island's vineyards on sandy loam and clay over limestone.","producers":["Pelee Island Winery"],"rslug":"ontario"},"ca-south-kelowna-slopes":{"name":"South Kelowna Slopes","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Pinot Noir, Riesling, Chardonnay, Gewürztraminer","summary":"A sub-GI (2022) of about 800 ha on the slopes above the east side of Okanagan Lake south of Kelowna, home to historic vineyards such as CedarCreek and St. Hubertus; cool, lake-moderated Pinot Noir and Riesling.","producers":["CedarCreek","St. Hubertus"],"rslug":"british-columbia"},"ca-st-davids-bench":{"name":"St. David's Bench","cat":"VQA","region":"Ontario","subregion":"Niagara-on-the-Lake","styles":["white","red","sweet"],"summary":"A raised bench at the foot of the escarpment around St. Davids, with the highest heat accumulation in Niagara (about 1,637 growing degree days); well-drained, sloping soils over the escarpment's lower terrace. Château des Charmes's château stands here.","producers":["Château des Charmes","Ravine Vineyard","Two Sisters"],"rslug":"ontario"},"ca-summerland-bench":{"name":"Summerland Bench","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Pinot Noir, Chardonnay, Riesling, Gewürztraminer","summary":"A sub-GI (2022) on the bench above the town of Summerland, with about 60 ha of vineyards and gentle, sunny slopes of glacial silt; Pinot Noir, Chardonnay and aromatic whites.","rslug":"british-columbia"},"ca-summerland-lakefront":{"name":"Summerland Lakefront","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Pinot Noir, Chardonnay, Pinot Gris, Riesling","summary":"A sub-GI (2022) of about 805 ha along the Okanagan Lake shoreline at Summerland, including Trout Creek, where the lake keeps temperatures mild; Pinot Noir, Chardonnay and sparkling.","rslug":"british-columbia"},"ca-summerland-valleys":{"name":"Summerland Valleys","cat":"GI","region":"British Columbia","subregion":"Okanagan Valley","created":"2022","styles":["red","white"],"grapes":"Pinot Noir, Riesling, Gewürztraminer","summary":"A sub-GI (2022) of about 1,350 ha in the side valleys west of Summerland, including Prairie Valley and Garnet Valley, higher and cooler than the lakeshore. Orchards share the land with vines; cooler nights suit Pinot Noir and aromatic whites.","rslug":"british-columbia"},"ca-thompson-valley":{"name":"Thompson Valley","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"2018","styles":["red","white"],"grapes":"Riesling, Pinot Noir, Gewürztraminer, Marquette","summary":"A GI (2018) around Kamloops on the Thompson River, semi-arid with cold winters, where growers favour hardier varieties and site selection on slopes above the frost-prone valley floor.","producers":["Monte Creek","Harper's Trail"],"rslug":"british-columbia"},"ca-tidal-bay":{"name":"Tidal Bay","cat":"Appellation","region":"Nova Scotia","created":"2011","styles":["white"],"grapes":"L'Acadie Blanc, Seyval Blanc, Vidal, Geisenheim 318, Ortega, Chardonnay","summary":"Nova Scotia's appellation-style designation, created by the province's wineries in 2011 with a first vintage in 2012. Tidal Bay is a crisp, aromatic, low-alcohol white blend that must be at least 51 percent L'Acadie Blanc, Seyval Blanc, Vidal and Geisenheim 318 (with 16 other varieties allowed), made from 100 percent Nova Scotia grapes and approved by a blind-tasting panel. It is meant to taste of the sea air of the Bay of Fundy and to pair with local scallops and lobster.","producers":["Benjamin Bridge","Lightfoot & Wolfville","Luckett","Domaine de Grand Pré","L'Acadie Vineyards","Jost"],"rslug":"nova-scotia"},"ca-twenty-mile-bench":{"name":"Twenty Mile Bench","cat":"VQA","region":"Ontario","subregion":"Niagara Escarpment","styles":["white","red","sweet"],"summary":"A bench sub-appellation around Jordan and Vineland, cut by Twenty Mile Creek ravines, with steep, limestone-rich slopes and cooling breezes (about 1,523 growing degree days). Home of Cave Spring (1986) and Tawse and some of Ontario's best Riesling and Chardonnay.","producers":["Cave Spring","Tawse","Flat Rock","Malivoire","Le Clos Jordanne (sourcing)"],"rslug":"ontario"},"ca-vancouver-island":{"name":"Vancouver Island","cat":"GI","region":"British Columbia","subregion":"British Columbia","created":"1990","styles":["red","white"],"grapes":"Pinot Noir, Pinot Gris, Ortega, Chardonnay","summary":"A coastal GI covering the island's southeast, sheltered from Pacific storms by the island's mountains. Cool and sunny in summer; Pinot Noir, Pinot Gris, Ortega and sparkling. Cowichan Valley is its sub-GI.","producers":["Blue Grouse","Averill Creek","Unsworth","Rocky Creek"],"contains":["Cowichan Valley"],"rslug":"british-columbia"},"ca-vin-de-glace-du-quebec":{"name":"Vin de glace du Québec","cat":"IGP","region":"Quebec","styles":["sweet"],"grapes":"Vidal","summary":"Quebec's IGP for icewine, from grapes (mostly Vidal) frozen naturally on the vine and pressed while frozen, so only concentrated, sugar-rich juice runs off. Quebec's severe winters make icewine a natural speciality, sold alongside the province's ice cider.","producers":["L'Orpailleur","Vignoble du Marathonien"],"rslug":"quebec"},"ca-vin-du-quebec":{"name":"Vin du Québec","cat":"IGP","region":"Quebec","styles":["white","red","rose","sparkling"],"grapes":"Frontenac, Marquette, Vidal, Seyval Blanc, Vandal-Cliche, Sainte-Croix","summary":"Quebec's protected geographical indication for wine (IGP), requiring 100 percent Quebec-grown grapes, independent certification and production standards; it covers still, sparkling, fortified and late-harvest wines from hybrids and vinifera. Most IGP wines come from Montérégie and the Eastern Townships around Dunham.","producers":["L'Orpailleur","Domaine des Côtes d'Ardoise","Les Pervenches","Vignoble de la Bauge"],"rslug":"quebec"},"ca-vinemount-ridge":{"name":"Vinemount Ridge","cat":"VQA","region":"Ontario","subregion":"Niagara Peninsula","styles":["white","red","sweet"],"summary":"The highest and coolest Niagara sub-appellation, on the top ridge of the escarpment above the benches, with the shortest frost-free season (about 178 days) and lowest heat (about 1,469 growing degree days). Riesling and icewine thrive; cold winters are a risk.","producers":["Kew Vineyards","Di Profio"],"rslug":"ontario"}}};
